import {useEffect,useState,type ReactNode} from 'react';
import {Home,Compass,Users,CalendarDays,BookOpen,ScrollText,ChartNoAxesColumnIncreasing,Bell,Settings,UserRound,LogOut,ShieldCheck,Plus,ChevronRight,Search,Check,Clock,LayoutDashboard,Swords,Coins,Menu,CheckCircle2,AlertTriangle,Castle} from 'lucide-react';
import type {State,Page,GameTable,Session,Community} from './types';
import {api,slots,members,STATUS,ROLE,DOW,SYSTEMS,money,date,today,tableImage,nextSessions} from './utils';
const cover={home:'/assets/hero-castelo.webp',explore:'/assets/castelo-dragao.webp',master:'/assets/salao-d20.webp',player:'/assets/bastiao.webp',admin:'/assets/hero-castelo.webp'};
const asString=(v:FormDataEntryValue|null)=>String(v||'');
const names:Record<Page,string>={inicio:'Início',login:'Acessar',painel:'Visão Geral',explorar:'Explorar Mesas',comunidades:'Comunidades','administrar-comunidades':'Gerenciar Comunidades','minhas-mesas':'Minhas Mesas',inscricoes:'Inscrições e Vagas',agenda:'Calendário e Sessões',presencas:'Presenças',usuarios:'Usuários e Mestres',mensalidades:'Mensalidades',relatorios:'Relatórios',notificacoes:'Notificações',preferencias:'WhatsApp e Preferências',perfil:'Meu Perfil'};
const eventLabels:Record<string,string>={vacancy:'Vagas disponíveis',approval:'Aprovações de inscrição',request:'Solicitações',session:'Mudanças nas sessões',reminder:'Lembretes',community:'Avisos da comunidade'};
function D20({size=34}: {size?:number}){return <svg width={size} height={size} viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="M32 3 57 18v28L32 61 7 46V18L32 3Z" stroke="#C6A15B" strokeWidth="2.1"/><path d="M7 18 32 30 57 18M7 46l25-16 25 16M32 3v27m0 0v31M7 18l25-15 25 15" stroke="#C6A15B" strokeWidth="1.7" opacity=".82"/><text x="32" y="42" textAnchor="middle" fill="#F2F0E8" fontSize="14" fontFamily="Georgia">20</text></svg>}
function Button({children,onClick,kind='primary',disabled=false,type='button',className=''}:{children:ReactNode;onClick?:()=>void;kind?:'primary'|'secondary'|'danger';disabled?:boolean;type?:'submit'|'button';className?:string}){return <button type={type} disabled={disabled} onClick={onClick} className={`${kind} ${className}`}>{children}</button>}
function Badge({value}:{value:string}){let cls=['approved','open','paid','present','scheduled'].includes(value)?'':(['rejected','closed','archived','cancelled','late','absent'].includes(value)?'red':(['pending','waitlisted'].includes(value)?'gold':'gray'));return <span className={`chip ${cls}`}>{STATUS[value]||value}</span>}
function Panel({title,children,action,className=''}:{title:string;children:ReactNode;action?:ReactNode;className?:string}){return <section className={`glass rounded-xl p-5 ${className}`}><div className="mb-4 flex items-center justify-between gap-3"><h3 className="text-[1.15rem] text-ivory">{title}</h3>{action}</div>{children}</section>}
function Metric({label,value,icon}:{label:string;value:string|number;icon:ReactNode}){return <div className="stat flex items-center gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-gold/40 text-gold">{icon}</div><div className="min-w-0"><div className="display truncate text-[1.8rem] leading-8">{value}</div><div className="text-xs text-mist">{label}</div></div></div>}
function Input({label,name,type='text',defaultValue,placeholder,required=false,min,max,minLength}:{label:string;name:string;type?:string;defaultValue?:string|number;placeholder?:string;required?:boolean;min?:string|number;max?:string|number;minLength?:number}){return <label className="block"><span className="label">{label}</span><input className="field" name={name} type={type} defaultValue={defaultValue} placeholder={placeholder} required={required} min={min} max={max} minLength={minLength}/></label>}
function Select({label,name,options,defaultValue,required=false}:{label:string;name:string;options:[string,string][];defaultValue?:string;required?:boolean}){return <label className="block"><span className="label">{label}</span><select className="field" name={name} defaultValue={defaultValue} required={required}>{options.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select></label>}
function TextArea({label,name,defaultValue,required=false}:{label:string;name:string;defaultValue?:string;required?:boolean}){return <label className="block"><span className="label">{label}</span><textarea className="field min-h-24" name={name} defaultValue={defaultValue} required={required}/></label>}
function Empty({text}:{text:string}){return <div className="rounded-lg border border-dashed border-gold/25 px-5 py-10 text-center text-sm text-mist">{text}</div>}
function Avatar({name}:{name:string}){return <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-gold/55 bg-[#304331] font-serif text-sm text-sun">{name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}</span>}
export default function App(){
 const [data,setData]=useState<State|null>(null),[page,setPage]=useState<Page>('inicio'),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[loginTab,setLoginTab]=useState<'login'|'register'>('login'),[showMenu,setShowMenu]=useState(false),[focusTable,setFocusTable]=useState('t1');
 const [editingTable,setEditingTable]=useState<GameTable|null>(null),[showTableForm,setShowTableForm]=useState(false),[showCommunityForm,setShowCommunityForm]=useState(false),[editingCommunity,setEditingCommunity]=useState<Community|null>(null),[showSessionForm,setShowSessionForm]=useState(false),[editingSession,setEditingSession]=useState<Session|null>(null);
 const [filterText,setFilterText]=useState(''),[filterSystem,setFilterSystem]=useState(''),[filterDay,setFilterDay]=useState(''),[filterMode,setFilterMode]=useState(''),[filterFree,setFilterFree]=useState('');
 const me=data?.me;
 const refresh=async()=>{try{setData(await api<State>('/state'));}catch{setData(null)}};
 useEffect(()=>{void refresh()},[]);
 const goto=(p:Page)=>{setPage(p);setShowMenu(false);window.scrollTo({top:0,behavior:'instant'})};
 const run=async<T,>(task:()=>Promise<T>,success='Alterações salvas com sucesso.')=>{setBusy(true);try{const result=await task();await refresh();setNotice(success);window.setTimeout(()=>setNotice(''),4400);return result}catch(err){setNotice(err instanceof Error?err.message:'Não foi possível concluir');window.setTimeout(()=>setNotice(''),5200);return undefined}finally{setBusy(false)}};
 const login=async(email:string,password:string)=>{const result=await run(()=>api('/login','POST',{email,password}),'Bem-vindo à Aurorium.');if(result)goto('painel')};
 const logout=async()=>{await api('/logout','POST');setData(null);goto('inicio')};
 const user=(id:string)=>data?.users.find(u=>u.id===id);
 const community=(id:string)=>data?.communities.find(c=>c.id===id);
 const table=(id:string)=>data?.tables.find(t=>t.id===id);
 const masterPerm=(t:GameTable)=>!!me&&(me.role==='admin'&&community(t.communityId)?.adminId===me.id||me.role==='master'&&t.masterId===me.id&&me.masterCommunities?.includes(t.communityId));
 const managed=data?.tables.filter(t=>masterPerm(t))||[];
 const myAccepted=data?.requests.filter(r=>r.userId===me?.id&&r.status==='approved').map(r=>table(r.tableId)).filter((x):x is GameTable=>!!x)||[];
 const mySessions=data?nextSessions(data).filter(s=>me?.role==='player'?myAccepted.some(t=>t.id===s.tableId):managed.some(t=>t.id===s.tableId)):[];
 const activeCount=data?.tables.filter(t=>t.status==='open').length||0;
 const filtered=data?.tables.filter(t=>{const comm=community(t.communityId);return (!filterText||`${t.name} ${t.system} ${user(t.masterId)?.name||''}`.toLowerCase().includes(filterText.toLowerCase()))&&(!filterSystem||t.system===filterSystem)&&(!filterDay||t.days.includes(Number(filterDay)))&&(!filterMode||t.mode===filterMode)&&(!filterFree||comm?.type===filterFree)})||[];
 const selected=table(focusTable)||filtered[0];
 const sessionNotif=data?.notices.filter(n=>!n.read).length||0;
 const actions=me?.role==='admin'?[['painel',LayoutDashboard],['explorar',Compass],['comunidades',Castle],['administrar-comunidades',Castle],['minhas-mesas',Swords],['inscricoes',ScrollText],['agenda',CalendarDays],['presencas',CheckCircle2],['usuarios',Users],['mensalidades',Coins],['relatorios',ChartNoAxesColumnIncreasing],['notificacoes',Bell],['preferencias',Settings],['perfil',UserRound]]:me?.role==='master'?[['painel',LayoutDashboard],['explorar',Compass],['minhas-mesas',Swords],['comunidades',Castle],['inscricoes',ScrollText],['agenda',CalendarDays],['presencas',CheckCircle2],['notificacoes',Bell],['preferencias',Settings],['perfil',UserRound]]:[['painel',LayoutDashboard],['explorar',Compass],['minhas-mesas',BookOpen],['comunidades',Castle],['inscricoes',ScrollText],['agenda',CalendarDays],['notificacoes',Bell],['preferencias',Settings],['perfil',UserRound]];
 const scene=page==='inicio'?cover.home:page==='login'?cover.master:page==='explorar'||page==='comunidades'?cover.explore:me?.role==='admin'?cover.admin:me?.role==='master'?cover.master:cover.player;
 function Topbar(){return <header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b border-gold/15 bg-[#061710]/95 px-4 backdrop-blur-xl md:px-7"><button className="mr-2 flex items-center gap-3" onClick={()=>goto('inicio')}><D20 size={38}/><span className="text-left"><strong className="display block text-[1.28rem] tracking-[.24em] text-sun">AURORIUM</strong><span className="block text-[.54rem] tracking-[.2em] text-mist">COMUNIDADES DE RPG</span></span></button><nav className="hidden items-center gap-5 text-sm text-mist lg:flex"><button onClick={()=>goto('inicio')} className={page==='inicio'?'text-gold':''}>Início</button><button onClick={()=>goto('comunidades')} className={page==='comunidades'?'text-gold':''}>Comunidades</button><button onClick={()=>goto('explorar')} className={page==='explorar'?'text-gold':''}>Explorar Mesas</button>{me&&<button onClick={()=>goto('painel')} className={page==='painel'?'text-gold':''}>Meu Painel</button>}</nav><div className="flex items-center gap-3">{me?<><button onClick={()=>goto('notificacoes')} className="relative rounded-lg border border-gold/20 p-2 text-gold"><Bell size={19}/>{sessionNotif>0&&<span className="absolute -right-2 -top-2 rounded-full bg-[#b85c4f] px-[5px] text-[10px] text-white">{sessionNotif}</span>}</button><button onClick={()=>goto('perfil')} className="hidden items-center gap-2 text-left sm:flex"><Avatar name={me.name}/><span className="text-xs"><strong className="block">{me.name.split(' ')[0]}</strong><span className="text-mist">{ROLE[me.role]}</span></span></button><button className="secondary !p-2" aria-label="Sair" title="Sair" onClick={()=>void logout()}><LogOut size={16}/></button></>:<Button onClick={()=>goto('login')}>Entrar <ChevronRight size={14}/></Button>}{me&&<button className="secondary !p-2 lg:hidden" onClick={()=>setShowMenu(!showMenu)}><Menu size={20}/></button>}</div></header>}
 function Sidebar(){return <aside className={`${showMenu?'block':'hidden'} fixed left-0 top-[76px] z-30 h-[calc(100vh-76px)] w-[245px] overflow-y-auto border-r border-gold/15 bg-[#081c15]/98 px-3 py-5 lg:sticky lg:top-[76px] lg:block`}><div className="eyebrow mb-5 px-3">Área {ROLE[me?.role||'player']}</div><div className="space-y-1">{actions.map(([id,Icon])=>{const P=id as Page;const I=Icon as typeof Home;return <button key={P} onClick={()=>goto(P)} className={`side-link ${page===P?'active':''}`}><I size={17}/><span>{names[P]}</span></button>})}</div><div className="glass-soft mt-7 rounded-xl px-4 py-5"><D20 size={28}/><p className="display mt-4 text-lg">Uma comunidade.<br/>Grandes aventuras.</p><p className="mt-2 text-xs leading-5 text-mist">Uma plataforma para quem transforma histórias em encontros.</p><button onClick={()=>goto('inicio')} className="mt-4 text-xs text-gold">Retornar à página inicial</button></div></aside>}
 const head=(title:string,sub:string,action?:ReactNode)=><div className="screen-title flex flex-wrap items-center justify-between gap-4"><div><span className="eyebrow">Aurorium / {ROLE[me?.role||'player']}</span><h1 className="mt-2">{title}</h1><p className="mt-2 max-w-2xl text-sm text-mist">{sub}</p></div>{action}</div>;
 function Landing(){return <main className="mx-auto max-w-[1540px] px-4 py-7 md:px-9"><section className="hero-outer px-7 py-16 md:px-16"><div className="max-w-[670px]"><span className="eyebrow">Onde histórias encontram sua comunidade</span><h1 className="mt-6 text-[clamp(2.7rem,5vw,5.2rem)] leading-[1.06]">Todo grande universo começa com uma <span className="text-sun">comunidade.</span></h1><p className="mt-6 max-w-[590px] text-base leading-7 text-[#ccd4c8]">Encontre mesas, organize campanhas e conecte jogadores e mestres em uma única plataforma.</p><div className="mt-9 flex flex-wrap gap-3"><Button onClick={()=>goto('explorar')}>Explorar mesas <ChevronRight size={16}/></Button><Button kind="secondary" onClick={()=>goto(me?'painel':'login')}>{me?'Meu painel':'Começar agora'}</Button></div><div className="mt-12 flex flex-wrap gap-5 text-xs text-mist"><span>◆ Jogadores</span><span>◆ Mestres</span><span>◆ Administradores</span></div></div></section><div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-4"><Metric label="Membros registrados" value={data?.users.length||21} icon={<Users size={19}/>}/><Metric label="Mesas disponíveis" value={activeCount||6} icon={<Swords size={19}/>}/><Metric label="Comunidades" value={data?.communities.length||2} icon={<Castle size={19}/>}/><Metric label="Sistemas de RPG" value={new Set(data?.tables.map(t=>t.system)||SYSTEMS).size} icon={<BookOpen size={19}/>}/></div><div className="mt-11 grid grid-cols-1 gap-5 lg:grid-cols-[1.15fr_.85fr]"><Panel title="Descubra comunidades" action={<button onClick={()=>goto('comunidades')} className="text-xs text-gold">Ver todas →</button>}><div className="grid gap-3 sm:grid-cols-2">{(data?.communities||[]).slice(0,2).map((c,i)=><div key={c.id} className="overflow-hidden rounded-lg border border-gold/15 bg-[#091b14]"><img className="h-36 w-full object-cover" src={i?cover.player:cover.explore} alt="Castelo e paisagem de fantasia"/><div className="p-3"><h3 className="text-base">{c.name}</h3><p className="mt-2 text-xs leading-5 text-mist">{c.description}</p><button onClick={()=>goto('comunidades')} className="mt-3 text-xs text-gold">Conhecer comunidade →</button></div></div>)}</div></Panel><Panel title="Próximas aventuras" action={<button onClick={()=>goto('explorar')} className="text-xs text-gold">Ver mesas →</button>}>{(data?.tables||[]).slice(0,4).map(t=><button onClick={()=>{setFocusTable(t.id);goto('explorar')}} key={t.id} className="row flex w-full items-center gap-3 text-left"><img src={tableImage(t.system)} className="h-12 w-16 rounded-md object-cover" alt=""/><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{t.name}</strong><span className="text-xs text-mist">{t.system} · {t.time}</span></span><Badge value={slots(t,data!.requests)?'open':'closed'}/></button>)}</Panel></div><div className="mt-8 text-center text-xs text-mist">Plataforma de gestão administrativa de RPG de mesa. Não substitui um VTT.</div></main>}
 function Login(){return <main className="mx-auto flex max-w-[1350px] flex-col justify-center px-4 py-8 md:min-h-[calc(100vh-76px)] md:px-8"><div className="grid overflow-hidden rounded-xl border border-gold/25 shadow-2xl lg:grid-cols-[.95fr_1.05fr]"><div className="min-h-[330px] bg-cover bg-center p-10 md:p-14" style={{backgroundImage:`linear-gradient(130deg,#071a14dd,#071a14a0),url('${cover.master}')`}}><D20 size={64}/><span className="eyebrow mt-12 block">Bem-vindo à Aurorium</span><h1 className="mt-5 max-w-[510px]">Mais que um jogo. <span className="text-gold">Uma comunidade.</span></h1><p className="mt-5 max-w-[400px] text-sm leading-7 text-mist">Sua próxima campanha merece uma organização à altura da aventura.</p></div><div className="bg-[#0a2119]/95 p-8 md:p-12"><div className="mb-7 flex gap-7 border-b border-gold/15 pb-4"><button className={loginTab==='login'?'text-gold':'text-mist'} onClick={()=>setLoginTab('login')}>Entrar</button><button className={loginTab==='register'?'text-gold':'text-mist'} onClick={()=>setLoginTab('register')}>Criar conta</button></div>{loginTab==='login'?<><h2>Acesse sua conta</h2><p className="mb-6 mt-2 text-sm text-mist">Acesso local para testar os três perfis do TCC.</p><form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void login(asString(f.get('email')),asString(f.get('password')))}}><Input label="E-mail" name="email" type="email" defaultValue="jogador@demo.rpg" required/><Input label="Senha" name="password" type="password" defaultValue="AuroriumDemo2026!" required/><Button type="submit" disabled={busy} className="w-full">Entrar no sistema</Button></form><div className="my-7 border-t border-gold/15"/><h3 className="mb-4">Contas de demonstração</h3><div className="grid grid-cols-3 gap-2">{[['Jogador','jogador@demo.rpg'],['Mestre','mestre@demo.rpg'],['Administrador','admin@demo.rpg']].map(([name,email])=><button key={email} onClick={()=>void login(email,'AuroriumDemo2026!')} className="rounded-lg border border-gold/25 bg-[#123427] p-3 text-xs text-ivory hover:border-gold"><ShieldCheck size={19} className="mx-auto mb-2 text-gold"/>{name}</button>)}</div></>:<><h2>Crie sua conta</h2><p className="my-3 text-sm text-mist">O novo usuário recebe o perfil Jogador.</p><form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(()=>api('/register','POST',{name:asString(f.get('name')),email:asString(f.get('email')),password:asString(f.get('password'))}),'Conta criada. Faça login.').then(r=>{if(r)setLoginTab('login')})}}><Input label="Nome completo" name="name" required/><Input label="E-mail" name="email" type="email" required/><Input label="Senha (mínimo 8 caracteres)" name="password" type="password" minLength={8} required/><Button type="submit" disabled={busy} className="w-full">Cadastrar</Button></form></>}<p className="mt-7 text-xs leading-5 text-mist">Ambiente demonstrativo. Não utilize senhas ou informações pessoais reais.</p></div></div></main>}
 function Explorer(){return <>{head('Explorar Mesas','Encontre aventuras que combinam com os seus horários e sistemas favoritos.')}<Panel title="Encontre sua próxima campanha"><div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5"><label className="col-span-2 md:col-span-1"><span className="label">Buscar por nome ou mestre</span><div className="relative"><Search size={16} className="absolute left-3 top-3.5 text-gold"/><input className="field !pl-9" value={filterText} onChange={e=>setFilterText(e.target.value)} placeholder="Nome, sistema, mestre..."/></div></label><label><span className="label">Sistema</span><select className="field" value={filterSystem} onChange={e=>setFilterSystem(e.target.value)}><option value="">Todos</option>{SYSTEMS.map(s=><option key={s}>{s}</option>)}</select></label><label><span className="label">Dia da semana</span><select className="field" value={filterDay} onChange={e=>setFilterDay(e.target.value)}><option value="">Qualquer dia</option>{DOW.map((d,i)=><option key={d} value={i}>{d}</option>)}</select></label><label><span className="label">Modalidade</span><select className="field" value={filterMode} onChange={e=>setFilterMode(e.target.value)}><option value="">Todas</option>{['Online','Presencial','Híbrida'].map(s=><option key={s}>{s}</option>)}</select></label><label><span className="label">Comunidade</span><select className="field" value={filterFree} onChange={e=>setFilterFree(e.target.value)}><option value="">Gratuita ou assinatura</option><option value="free">Gratuita</option><option value="paid">Por assinatura</option></select></label></div><div className="mt-4 flex items-center justify-between text-xs text-mist"><span>{filtered.length} mesas encontradas</span><button onClick={()=>{setFilterText('');setFilterDay('');setFilterSystem('');setFilterMode('');setFilterFree('')}} className="text-gold">Limpar filtros</button></div></Panel><div className="mt-5 grid grid-cols-1 items-start gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 2xl:grid-cols-3">{filtered.map(t=><button onClick={()=>setFocusTable(t.id)} className={`table-card text-left ${focusTable===t.id?'!border-gold':''}`} key={t.id}><div className="relative"><img src={tableImage(t.system)} className="cover" alt={`Ilustração da mesa ${t.name}`}/><div className="absolute right-3 top-3"><Badge value={t.status==='open'&&slots(t,data!.requests)===0?'closed':t.status}/></div></div><div className="p-4"><span className="eyebrow">{t.system}</span><h3 className="mt-2 min-h-[48px] text-[1.2rem] leading-6">{t.name}</h3><p className="line-clamp-2 min-h-[38px] text-xs leading-5 text-mist">{t.description}</p><div className="mt-4 flex flex-wrap gap-2 text-xs text-mist"><span className="flex items-center gap-1"><CalendarDays size={13}/>{t.days.map(i=>DOW[i]).join(', ')}</span><span className="flex items-center gap-1"><Clock size={13}/>{t.time}</span><span className="flex items-center gap-1"><Users size={13}/>{slots(t,data!.requests)} vagas</span></div><div className="mt-4 flex items-center justify-between border-t border-gold/15 pt-3"><span className="text-xs text-mist">{user(t.masterId)?.name||'Mestre'}</span><span className="text-xs text-gold">Ver detalhes →</span></div></div></button>)}{!filtered.length&&<Empty text="Nenhuma mesa encontrada. Experimente outros filtros."/>}</div>{selected?<aside className="glass sticky top-[96px] overflow-hidden rounded-xl"><img src={tableImage(selected.system)} className="h-52 w-full object-cover" alt={`Capa de ${selected.name}`}/><div className="p-5"><span className="eyebrow">Detalhes da campanha</span><h2 className="my-3 text-[1.55rem]">{selected.name}</h2><p className="text-sm text-mist">{selected.description}</p><div className="my-4 flex flex-wrap gap-2"><span className="chip gold">{selected.system}</span><span className="chip">{selected.mode}</span><Badge value={selected.status}/></div><div className="space-y-2 border-t border-gold/15 py-4 text-sm"><div>Comunidade: <strong className="text-gold">{community(selected.communityId)?.name}</strong></div><div>Mestre: {user(selected.masterId)?.name}</div><div>Dias: {selected.days.map(i=>DOW[i]).join(', ')} às {selected.time}</div><div>Ocupação: {members(selected,data!.requests).length}/{selected.capacity} jogadores</div><div>Vagas livres: {slots(selected,data!.requests)}</div></div><p className="mb-4 text-xs text-mist">Regras: {selected.rules}</p>{me?.role==='player'?(()=>{const r=data!.requests.find(r=>r.tableId===selected.id&&r.userId===me.id&&['approved','pending','waitlisted'].includes(r.status));return r?<div className="flex flex-wrap items-center gap-2"><Badge value={r.status}/>{r.status!=='approved'&&<Button kind="secondary" disabled={busy} onClick={()=>void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'cancelled'}),'Solicitação cancelada.')}>Cancelar solicitação</Button>}</div>:<Button disabled={busy||selected.status!=='open'} onClick={()=>void run(()=>api('/requests','POST',{tableId:selected.id}),slots(selected,data!.requests)>0?'Solicitação enviada ao mestre.':'Você entrou na lista de espera.')} className="w-full">{slots(selected,data!.requests)>0?'Solicitar participação':selected.waitlist?'Entrar na lista de espera':'Mesa lotada'}</Button>})():masterPerm(selected)?<Button onClick={()=>{setEditingTable(selected);setShowTableForm(true);goto('minhas-mesas')}}>Gerenciar esta mesa</Button>:<Button kind="secondary" onClick={()=>goto('agenda')}>Ver sessões</Button>}</div></aside>:<Empty text="Selecione uma mesa"/>}</div></>}
 function Communities(){return <>{head('Comunidades','Espaços para jogadores, mestres e campanhas organizadas.',me?.role==='admin'?<Button onClick={()=>{setEditingCommunity(null);setShowCommunityForm(true)}}><Plus size={16}/> Nova comunidade</Button>:undefined)}{showCommunityForm&&me?.role==='admin'&&<Panel title={editingCommunity?'Editar comunidade':'Nova comunidade'} className="mb-5"><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload={name:asString(f.get('name')),description:asString(f.get('description')),type:asString(f.get('type')),rules:asString(f.get('rules')),fee:Number(f.get('fee'))};void run(()=>api(editingCommunity?`/communities/${editingCommunity.id}`:'/communities',editingCommunity?'PATCH':'POST',payload),'Comunidade salva.').then(r=>{if(r)setShowCommunityForm(false)})}}><Input label="Nome" name="name" defaultValue={editingCommunity?.name} required/><Select label="Tipo" name="type" defaultValue={editingCommunity?.type} options={ [['free','Gratuita'],['paid','Por assinatura']] }/><Input label="Valor de referência mensal" name="fee" type="number" min={0} defaultValue={editingCommunity?.fee||0}/><Input label="Descrição" name="description" defaultValue={editingCommunity?.description}/><div className="md:col-span-2"><TextArea label="Regras" name="rules" defaultValue={editingCommunity?.rules}/></div><div className="flex gap-2"><Button type="submit" disabled={busy}>Salvar</Button><Button kind="secondary" onClick={()=>setShowCommunityForm(false)}>Fechar</Button></div></form></Panel>}<div className="grid gap-5 md:grid-cols-2">{data?.communities.map((c,i)=>{const count=data.users.filter(u=>u.joined?.includes(c.id)).length;return <article key={c.id} className="table-card"><img src={i%2?cover.player:cover.explore} className="h-56 w-full object-cover" alt="Paisagem fantástica com castelo"/><div className="p-6"><div className="flex flex-wrap justify-between gap-3"><h2>{c.name}</h2><span className="chip gold">{c.type==='paid'?'Por assinatura':'Gratuita'}</span></div><p className="mt-3 min-h-14 text-sm leading-6 text-mist">{c.description}</p><div className="my-5 flex flex-wrap gap-5 border-t border-gold/15 pt-4 text-sm text-mist"><span><Users className="mr-1 inline" size={16}/>{count} membros</span><span><Swords className="mr-1 inline" size={16}/>{data.tables.filter(t=>t.communityId===c.id).length} mesas</span></div><div className="flex flex-wrap gap-2">{me?.joined.includes(c.id)?<span className="chip">Você é membro</span>:me?<Button disabled={busy} onClick={()=>void run(()=>api('/join-community','POST',{communityId:c.id}),'Você ingressou na comunidade.')}>Participar</Button>:<Button onClick={()=>goto('login')}>Criar conta</Button>}{me?.role==='admin'&&c.adminId===me.id&&<Button kind="secondary" onClick={()=>{setEditingCommunity(c);setShowCommunityForm(true);window.scrollTo({top:0,behavior:'smooth'})}}>Editar</Button>}{me?.role==='player'&&!me.masterCommunities.includes(c.id)&&<Button kind="secondary" onClick={()=>void run(()=>api('/master-applications','POST',{communityId:c.id}),'Solicitação enviada ao administrador.')}>Solicitar ser mestre</Button>}</div></div></article>})}</div></>}
 function MyTables(){const mine=me?.role==='player'?myAccepted:managed;return <>{head(me?.role==='player'?'Minhas Mesas':'Gerenciar Mesas',me?.role==='player'?'Campanhas nas quais você já participa.':'Publicação de campanhas, inscrições, participantes e vagas.',me?.role!=='player'?<Button onClick={()=>{setEditingTable(null);setShowTableForm(true)}}><Plus size={16}/> Criar Mesa</Button>:<Button onClick={()=>goto('explorar')}>Explorar mesas</Button>)}{showTableForm&&me?.role!=='player'&&<TableEditor key={editingTable?.id||'new'} value={editingTable} onClose={()=>setShowTableForm(false)} onSaved={()=>setShowTableForm(false)}/>}<div className="grid gap-5 md:grid-cols-2 2xl:grid-cols-3">{mine.map(t=><article className="table-card" key={t.id}><img src={tableImage(t.system)} alt={`Arte de ${t.name}`} className="cover"/><div className="p-5"><span className="eyebrow">{t.system}</span><h3 className="mt-2 text-xl">{t.name}</h3><p className="mt-2 text-xs text-mist">{community(t.communityId)?.name}</p><div className="my-4 flex justify-between"><Badge value={t.status}/><span className="chip gold">{slots(t,data!.requests)} vagas disponíveis</span></div><div className="flex flex-wrap gap-2">{me?.role!=='player'?<><Button onClick={()=>{setEditingTable(t);setShowTableForm(true);window.scrollTo({top:0,behavior:'smooth'})}}>Editar</Button><Button kind="secondary" onClick={()=>goto('inscricoes')}>Inscrições</Button><Button kind="danger" onClick={()=>{if(window.confirm(`Arquivar a mesa ${t.name}?`))void run(()=>api(`/tables/${t.id}`,'DELETE',{}),'Mesa arquivada.')}}>Arquivar</Button></>:<Button kind="secondary" onClick={()=>goto('agenda')}>Ver calendário</Button>}</div></div></article>)}{!mine.length&&<Empty text="Nenhuma mesa associada ao seu perfil."/>}</div></>}
 function TableEditor({value,onClose,onSaved}:{value:GameTable|null;onClose:()=>void;onSaved:()=>void}){const allowed=data!.communities.filter(c=>me!.role==='admin'?c.adminId===me!.id:me!.masterCommunities.includes(c.id));const [days,setDays]=useState<number[]>(value?.days||[3]);const [preview,setPreview]=useState(value?.name||'Sua nova campanha');return <Panel title={value?'Editar mesa':'Criar uma nova mesa'} className="mb-7"><div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_300px]"><form className="space-y-5" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload={name:asString(f.get('name')),system:asString(f.get('system')),communityId:asString(f.get('communityId')),genre:asString(f.get('genre')),description:asString(f.get('description')),mode:asString(f.get('mode')),capacity:Number(f.get('capacity')),start:asString(f.get('start')),end:asString(f.get('end')),time:asString(f.get('time')),duration:Number(f.get('duration')),recurrence:asString(f.get('recurrence')),days,waitlist:f.has('waitlist'),status:asString(f.get('status')),rules:asString(f.get('rules'))};void run(()=>api(value?`/tables/${value.id}`:'/tables',value?'PATCH':'POST',payload),'Mesa salva e publicada.').then(r=>{if(r)onSaved()})}}><div className="eyebrow">01 · Informações gerais</div><div className="form-grid"><label><span className="label">Nome da campanha</span><input className="field" name="name" required defaultValue={value?.name} onChange={e=>setPreview(e.target.value)}/></label><Select label="Sistema de RPG" name="system" defaultValue={value?.system} options={SYSTEMS.map(s=>[s,s])}/><Select label="Comunidade" name="communityId" defaultValue={value?.communityId} options={allowed.map(c=>[c.id,c.name])}/><Select label="Modalidade" name="mode" defaultValue={value?.mode} options={['Online','Presencial','Híbrida'].map(x=>[x,x])}/><Input label="Gênero" name="genre" defaultValue={value?.genre||'Fantasia'}/><Select label="Situação" name="status" defaultValue={value?.status} options={ [['open','Publicada'],['closed','Encerrada'],['archived','Arquivada']] }/><div className="md:col-span-2"><TextArea label="Descrição" name="description" required defaultValue={value?.description}/></div></div><div className="border-t border-gold/15 pt-4"><span className="eyebrow">02 · Participação</span><div className="form-grid mt-4"><Input label="Capacidade" name="capacity" type="number" min={1} max={30} defaultValue={value?.capacity||5} required/><label className="flex items-center gap-3 text-sm text-mist"><input className="accent-[#c6a15b]" type="checkbox" name="waitlist" defaultChecked={value?.waitlist!==false}/>Habilitar lista de espera</label><div className="md:col-span-2"><TextArea label="Regras" name="rules" defaultValue={value?.rules||'Respeito e pontualidade.'}/></div></div></div><div className="border-t border-gold/15 pt-4"><span className="eyebrow">03 · Agendamento</span><div className="form-grid mt-4"><Input label="Data inicial" name="start" type="date" required defaultValue={value?.start||today()}/><Input label="Data final" name="end" type="date" required defaultValue={value?.end||'2027-02-01'}/><Input label="Horário" name="time" type="time" required defaultValue={value?.time||'19:30'}/><Input label="Duração (horas)" name="duration" type="number" min={1} max={12} defaultValue={value?.duration||3}/><Select label="Recorrência" name="recurrence" defaultValue={value?.recurrence} options={ [['weekly','Semanal'],['biweekly','Quinzenal'],['monthly','Mensal'],['once','Única']] }/></div><div className="mt-5"><div className="label">Dias de sessão</div><div className="flex flex-wrap gap-2">{DOW.map((d,i)=><label key={d} className={`cursor-pointer rounded-lg border px-3 py-2 text-xs ${days.includes(i)?'border-gold bg-[#31422b]':'border-gold/20'}`}><input className="sr-only" type="checkbox" checked={days.includes(i)} onChange={()=>setDays(cur=>cur.includes(i)?cur.filter(x=>x!==i):[...cur,i])}/>{d}</label>)}</div></div></div><div className="flex flex-wrap gap-2"><Button type="submit" disabled={busy||!allowed.length}>Salvar mesa</Button><Button kind="secondary" onClick={onClose}>Cancelar</Button></div></form><div className="glass-soft overflow-hidden rounded-lg xl:sticky xl:top-28"><img src={tableImage(value?.system||'D&D 5e')} className="h-44 w-full object-cover" alt="Capa de fantasia medieval"/><div className="p-5"><span className="eyebrow">Pré-visualização</span><h3 className="mt-3 text-xl">{preview||'Sua nova mesa'}</h3><p className="mt-3 text-sm text-mist">{value?.system||'D&D 5e'}</p><div className="mt-4 flex gap-2"><span className="chip">{value?.mode||'Online'}</span><span className="chip gold">{value?.capacity||5} jogadores</span></div><p className="mt-5 border-t border-gold/20 pt-4 text-xs text-mist">Após salvar, o cadastro ficará disponível na exploração de mesas e nos painéis administrativos.</p></div></div></div></Panel>}
 function Dashboard(){if(!me||!data)return null;const t=me.role==='admin'?data.tables:me.role==='master'?managed:myAccepted;const reqs=me.role==='player'?data.requests.filter(r=>r.userId===me.id):data.requests.filter(r=>t.some(q=>q.id===r.tableId));const sessions=me.role==='player'?mySessions:nextSessions(data).filter(s=>t.some(x=>x.id===s.tableId));return <>{head(`Bem-vindo, ${me.name.split(' ')[0]}`,me.role==='player'?'Seu próximo capítulo começa aqui. Acompanhe suas mesas e inscrições.':me.role==='master'?'Gerencie suas campanhas, jogadores e próximas sessões.':'Uma visão executiva da sua comunidade de RPG.',me.role==='player'?<Button onClick={()=>goto('explorar')}><Compass size={16}/> Encontrar mesas</Button>:<Button onClick={()=>{setEditingTable(null);setShowTableForm(true);goto('minhas-mesas')}}><Plus size={16}/> Criar mesa</Button>)}<div className={`mb-6 grid grid-cols-2 gap-3 ${me.role==='admin'?'xl:grid-cols-4':'xl:grid-cols-4'}`}><Metric icon={<Swords size={19}/>} label={me.role==='player'?'Minhas mesas':'Mesas ativas'} value={t.length}/><Metric icon={<CalendarDays size={19}/>} label="Próximas sessões" value={sessions.length}/><Metric icon={<ScrollText size={19}/>} label="Solicitações pendentes" value={reqs.filter(r=>r.status==='pending').length}/><Metric icon={<Users size={19}/>} label={me.role==='player'?'Posições em espera':'Vagas disponíveis'} value={me.role==='player'?reqs.filter(r=>r.status==='waitlisted').length:t.reduce((n,x)=>n+slots(x,data.requests),0)}/>{me.role==='admin'&&<><Metric icon={<Users size={19}/>} label="Membros" value={data.users.length}/><Metric icon={<ShieldCheck size={19}/>} label="Mestres" value={data.users.filter(u=>u.role==='master').length}/><Metric icon={<Coins size={19}/>} label="Mensalidades pendentes" value={data.dues.filter(x=>x.status!=='paid').length}/><Metric icon={<Castle size={19}/>} label="Comunidades" value={data.communities.length}/></>}</div><div className="grid items-start gap-5 xl:grid-cols-[1.28fr_.92fr]"><div className="space-y-5"><Panel title={me.role==='player'?'Minhas aventuras':'Mesas sob minha gestão'} action={<button onClick={()=>goto('minhas-mesas')} className="text-xs text-gold">Ver todas →</button>}><div className="grid gap-3 sm:grid-cols-2">{t.slice(0,4).map(tb=><article key={tb.id} className="overflow-hidden rounded-lg border border-gold/15 bg-[#092019]"><img src={tableImage(tb.system)} className="h-36 w-full object-cover" alt={`Capa da mesa ${tb.name}`}/><div className="p-4"><span className="eyebrow">{tb.system}</span><h3 className="mt-2">{tb.name}</h3><p className="mt-2 text-xs text-mist">{DOW[tb.days[0]]} às {tb.time} · {slots(tb,data.requests)} vagas</p></div></article>)}{t.length===0&&<Empty text="Você ainda não participa de mesas."/>}</div></Panel><Panel title={me.role==='admin'?'Últimas atividades':'Próximas sessões'} action={<button onClick={()=>goto(me.role==='admin'?'relatorios':'agenda')} className="text-xs text-gold">Abrir →</button>}>{me.role==='admin'?(data.activity.slice(0,6).map(a=><div key={a.id} className="row flex gap-3 text-sm"><CheckCircle2 size={16} className="shrink-0 text-gold"/><div>{a.text}<div className="mt-1 text-xs text-mist">{new Date(a.date).toLocaleString('pt-BR')}</div></div></div>)):(sessions.slice(0,6).map(s=><button key={s.id} onClick={()=>goto('agenda')} className="row flex w-full items-center gap-4 text-left"><div className="rounded-lg border border-gold/25 p-3 text-gold"><CalendarDays size={20}/></div><span className="flex-1"><strong className="block text-sm">{table(s.tableId)?.name}</strong><span className="text-xs text-mist">{date(s.date)} · {s.time} · {s.duration}h</span></span><ChevronRight size={15} className="text-gold"/></button>))}{(me.role==='admin'?data.activity.length===0:sessions.length===0)&&<Empty text="Nenhum registro recente."/>}</Panel></div><div className="space-y-5"><Panel title="Agenda da semana"><MiniCalendar items={sessions}/></Panel><Panel title={me.role==='player'?'Avisos recentes':'Solicitações recebidas'}>{me.role==='player'?data.notices.slice(0,5).map(n=><div key={n.id} className="row flex gap-3"><Bell size={18} className="shrink-0 text-gold"/><div><p className="text-sm">{n.text}</p><p className="mt-1 text-xs text-mist">{new Date(n.date).toLocaleString('pt-BR')}</p></div></div>):reqs.filter(r=>r.status==='pending').slice(0,5).map(r=><div key={r.id} className="row flex items-center gap-2"><Avatar name={user(r.userId)?.name||'Jogador'}/><div className="flex-1 text-xs"><strong className="block">{user(r.userId)?.name}</strong><span className="text-mist">{table(r.tableId)?.name}</span></div><Button kind="secondary" onClick={()=>goto('inscricoes')}>Analisar</Button></div>)}{(me.role==='player'?data.notices.length===0:!reqs.some(r=>r.status==='pending'))&&<Empty text="Nenhum aviso pendente."/>}</Panel></div></div></>}
 function MiniCalendar({items}:{items:Session[]}){const [offset,setOffset]=useState(0);const [selectedDate,setSelectedDate]=useState(today());const nowDate=new Date();const month=new Date(nowDate.getFullYear(),nowDate.getMonth()+offset,1);const y=month.getFullYear(),m=month.getMonth(),first=month.getDay(),max=new Date(y,m+1,0).getDate();const cells=Array.from({length:first+max},(_,i)=>i<first?null:i-first+1);const stamp=(d:number)=>`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return <><div className="mb-4 flex items-center justify-between"><button className="secondary !px-3 !py-1" onClick={()=>setOffset(v=>v-1)}>‹</button><strong className="text-sm capitalize">{month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button className="secondary !px-3 !py-1" onClick={()=>setOffset(v=>v+1)}>›</button></div><div className="grid grid-cols-7 gap-1">{DOW.map(x=><div key={x} className="py-2 text-center text-[10px] uppercase text-mist">{x}</div>)}{cells.map((d,i)=>d?<button key={i} onClick={()=>setSelectedDate(stamp(d))} className={`cal-day ${items.some(s=>s.date===stamp(d))?'has':''} ${selectedDate===stamp(d)?'selected':''}`}>{d}{items.some(s=>s.date===stamp(d))&&<span className="mt-2 block h-1 w-1 rounded-full bg-gold"/>}</button>:<div key={i}/>)}</div><div className="mt-4 border-t border-gold/15 pt-3">{items.filter(s=>s.date===selectedDate).slice(0,3).map(s=><div key={s.id} className="mt-2 flex justify-between gap-3 text-xs"><span className="text-mist">{table(s.tableId)?.name||s.title}</span><strong className="text-gold">{s.time}</strong></div>)}{!items.some(s=>s.date===selectedDate)&&<p className="text-xs text-mist">Nenhuma sessão para a data selecionada.</p>}</div></>}
 function Requests(){const allRequests=me?.role==='player'?data!.requests.filter(r=>r.userId===me.id):data!.requests.filter(r=>managed.some(t=>t.id===r.tableId));const requestOrder:Record<string,number>={pending:0,waitlisted:1,approved:2,rejected:3,cancelled:4};const ordered=[...allRequests].sort((a,b)=>(requestOrder[a.status]??5)-(requestOrder[b.status]??5));return <>{head('Solicitações e Vagas',me?.role==='player'?'Acompanhe pedidos, aprovações e listas de espera.':'Aprove inscrições e gerencie o preenchimento de suas mesas.')}<Panel title={`${ordered.length} solicitações`}><div className="scroller"><table className="data-table"><thead><tr><th>Jogador</th><th>Mesa</th><th>Data</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{ordered.map(r=>{const t=table(r.tableId);return <tr key={r.id}><td>{user(r.userId)?.name}</td><td>{t?.name}</td><td>{date(r.date)}</td><td><Badge value={r.status}/></td><td><div className="flex gap-2">{me?.role==='player'?r.status!=='approved'&&r.status!=='cancelled'?<>{r.status==='waitlisted'&&t&&slots(t,data!.requests)>0&&<Button disabled={busy} onClick={()=>void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'pending'}),'Interesse confirmado. Aguarde aprovação do Mestre.')}>Confirmar interesse</Button>}<Button kind="secondary" disabled={busy} onClick={()=>void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'cancelled'}),'Inscrição cancelada.')}>Cancelar</Button></>:<span className="text-mist">-</span>:t&&masterPerm(t)&&['pending','waitlisted'].includes(r.status)?<><Button disabled={busy||slots(t,data!.requests)<1} onClick={()=>void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'approved'}),'Participante aprovado.')}>Aprovar</Button><Button kind="danger" onClick={()=>void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'rejected'}),'Solicitação rejeitada.')}>Rejeitar</Button></>:t&&masterPerm(t)&&r.status==='approved'?<Button kind="danger" onClick={()=>{if(window.confirm('Remover este participante?'))void run(()=>api(`/requests/${r.id}`,'PATCH',{status:'cancelled'}),'Participante removido e vaga liberada.')}}>Remover</Button>:<span className="text-mist">-</span>}</div></td></tr>})}</tbody></table>{!ordered.length&&<Empty text="Não há solicitações cadastradas."/>}</div></Panel></>}
 function Agenda(){const allowed=me?.role==='player'?myAccepted:managed;const ids=allowed.map(t=>t.id);const sessions=data!.sessions.filter(s=>ids.includes(s.tableId)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return <>{head('Agenda e Sessões','Visualize, crie, reagende e acompanhe as sessões de suas campanhas.',me?.role!=='player'?<Button onClick={()=>{setEditingSession(null);setShowSessionForm(true)}}><Plus size={16}/> Agendar sessão</Button>:undefined)}{showSessionForm&&me?.role!=='player'&&<Panel title={editingSession?'Editar ocorrência':'Criar sessões'} className="mb-5"><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload=editingSession?{date:asString(f.get('date')),time:asString(f.get('time')),title:asString(f.get('title')),status:asString(f.get('status')),scope:asString(f.get('scope'))}:{tableId:asString(f.get('tableId')),title:asString(f.get('title')),start:asString(f.get('date')),end:asString(f.get('end')),time:asString(f.get('time')),duration:Number(f.get('duration')),recurrence:asString(f.get('recurrence')),days:(allowed.find(t=>t.id===asString(f.get('tableId')))?.days)||[3]};void run(()=>api(editingSession?`/sessions/${editingSession.id}`:'/sessions',editingSession?'PATCH':'POST',payload),'Sessões atualizadas.').then(r=>{if(r){setShowSessionForm(false);setEditingSession(null)}})}}>{!editingSession&&<Select label="Mesa" name="tableId" options={allowed.map(t=>[t.id,t.name])}/>}<Input label="Título" name="title" defaultValue={editingSession?.title||'Sessão de campanha'} required/><Input label="Data inicial" name="date" type="date" defaultValue={editingSession?.date||today()} required/><Input label="Horário" name="time" type="time" defaultValue={editingSession?.time||'19:30'} required/>{!editingSession?<><Input label="Data final" name="end" type="date" defaultValue="2027-02-01" required/><Input label="Duração (horas)" name="duration" type="number" min={1} defaultValue={3}/><Select label="Recorrência" name="recurrence" options={ [['once','Sessão avulsa'],['weekly','Semanal'],['biweekly','Quinzenal'],['monthly','Mensal']] }/></>:<><Select label="Situação" name="status" defaultValue={editingSession.status} options={ [['scheduled','Agendada'],['completed','Realizada'],['cancelled','Cancelada']] }/><Select label="Aplicar alteração" name="scope" options={ [['one','Somente esta ocorrência'],['future','Esta e as futuras da série']] }/></>}<div className="flex gap-2"><Button type="submit" disabled={busy}>Salvar</Button><Button kind="secondary" onClick={()=>setShowSessionForm(false)}>Cancelar</Button></div></form><p className="mt-3 text-xs text-mist">As ocorrências seguem os dias configurados na mesa e o período escolhido. A alteração de uma ocorrência não altera a série toda.</p></Panel>}<div className="grid gap-5 xl:grid-cols-[390px_1fr]"><Panel title="Calendário"><MiniCalendar items={sessions}/></Panel><Panel title="Sessões das minhas mesas"><div className="max-h-[700px] overflow-y-auto">{sessions.slice(0,70).map(s=><div key={s.id} className="row flex flex-wrap items-center gap-3"><div className="min-w-[83px] rounded-lg border border-gold/25 p-3 text-center"><strong className="display block text-lg text-gold">{new Date(s.date+'T12:00:00').getDate()}</strong><span className="text-[10px] uppercase text-mist">{new Date(s.date+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'})}</span></div><div className="min-w-[130px] flex-1"><strong className="text-sm">{table(s.tableId)?.name}</strong><div className="mt-1 text-xs text-mist">{s.title} · {s.time} · {s.duration}h</div></div><Badge value={s.status}/>{me?.role!=='player'&&<Button kind="secondary" onClick={()=>{setEditingSession(s);setShowSessionForm(true);window.scrollTo({top:0,behavior:'smooth'})}}>Editar</Button>}</div>)}{!sessions.length&&<Empty text="Ainda não existem sessões disponíveis."/>}</div></Panel></div></>}
 function Attendance(){const t=managed;const sessions=data!.sessions.filter(s=>t.some(x=>x.id===s.tableId)).sort((a,b)=>b.date.localeCompare(a.date));const [sessionId,setSessionId]=useState(sessions[0]?.id||'');const session=sessions.find(s=>s.id===sessionId)||sessions[0];const game=session?table(session.tableId):null;const people=game?members(game,data!.requests):[];return <>{head('Registro de Presença','Registre a participação dos jogadores sem perder o histórico.')}{session?<div className="grid gap-5 xl:grid-cols-[1fr_330px]"><Panel title={`Presenças - ${game?.name}`} action={<select value={session.id} onChange={e=>setSessionId(e.target.value)} className="field !w-auto max-w-[250px]">{sessions.map(s=><option key={s.id} value={s.id}>{date(s.date)} · {table(s.tableId)?.name}</option>)}</select>}><div className="scroller"><table className="data-table"><thead><tr><th>Jogador</th><th>Presença</th><th>Ação</th></tr></thead><tbody>{people.map(r=>{const u=user(r.userId);return <tr key={r.id}><td>{u?.name}</td><td><Badge value={session.attendance?.[r.userId]||'unmarked'}/></td><td><div className="flex gap-2"><Button disabled={busy} onClick={()=>void run(()=>api(`/sessions/${session.id}/attendance`,'PATCH',{userId:r.userId,value:'present'}),'Presença registrada.')}>Presente</Button><Button kind="secondary" disabled={busy} onClick={()=>void run(()=>api(`/sessions/${session.id}/attendance`,'PATCH',{userId:r.userId,value:'absent'}),'Ausência registrada.')}>Ausente</Button></div></td></tr>})}</tbody></table>{!people.length&&<Empty text="Ainda não existem participantes aprovados."/>}</div></Panel><Panel title="Resumo da sessão"><div className="space-y-4"><Metric icon={<Check size={19}/>} label="Presentes" value={Object.values(session.attendance||{}).filter(s=>s==='present').length}/><Metric icon={<AlertTriangle size={19}/>} label="Ausentes" value={Object.values(session.attendance||{}).filter(s=>s==='absent').length}/><Metric icon={<Users size={19}/>} label="Jogadores aprovados" value={people.length}/></div></Panel></div>:<Empty text="Não existem sessões sob sua responsabilidade."/>}</>}
 function AdminUsers(){const allowed=data!.communities.filter(c=>c.adminId===me?.id);const applications=data!.masterApplications.filter(a=>allowed.some(c=>c.id===a.communityId));const clients=data!.users.filter(u=>u.joined?.some(cid=>allowed.some(c=>c.id===cid))||allowed.some(c=>c.adminId===u.id));return <>{head('Usuários e Mestres','Acompanhe membros e autorize mestres em suas comunidades.')}<div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Panel title="Membros da comunidade"><div className="scroller"><table className="data-table"><thead><tr><th>Membro</th><th>E-mail</th><th>Perfil</th><th>Permissões</th><th>Ação</th></tr></thead><tbody>{clients.map(u=><tr key={u.id}><td><div className="flex items-center gap-2"><Avatar name={u.name}/>{u.name}</div></td><td>{u.email}</td><td>{ROLE[u.role]}</td><td>{u.masterCommunities?.map(id=>community(id)?.name).join(', ')||'Jogador'}</td><td>{u.role==='player'&&allowed.length>0?<Button disabled={busy} onClick={()=>void run(()=>api(`/users/${u.id}`,'PATCH',{action:'approve-master',communityId:allowed[0].id}),'Mestre habilitado.')}>Habilitar Mestre</Button>:<span className="text-xs text-mist">Sem ação</span>}</td></tr>)}</tbody></table></div></Panel><Panel title="Solicitações para se tornar Mestre"><div>{applications.length?applications.map(a=><div key={a.id} className="row"><div className="flex flex-wrap items-center justify-between gap-2"><div><strong>{user(a.userId)?.name}</strong><p className="mt-1 text-xs text-mist">{community(a.communityId)?.name}</p></div><Badge value={a.status}/></div>{a.status==='pending'&&<div className="mt-3 flex gap-2"><Button disabled={busy} onClick={()=>void run(()=>api(`/master-applications/${a.id}`,'PATCH',{status:'approved'}),'Solicitação aprovada.')}>Aprovar</Button><Button kind="danger" disabled={busy} onClick={()=>void run(()=>api(`/master-applications/${a.id}`,'PATCH',{status:'rejected'}),'Solicitação rejeitada.')}>Rejeitar</Button></div>}</div>):<Empty text="Não há solicitações de habilitação."/>}</div></Panel></div></>}
 function AdminCommunities(){const allowed=data!.communities.filter(c=>c.adminId===me?.id);return <>{head('Gerenciar Comunidades','Edite os espaços, regras e tipos de participação.',<Button onClick={()=>{setEditingCommunity(null);setShowCommunityForm(true)}}><Plus size={15}/> Nova comunidade</Button>)}{showCommunityForm&&<Panel title={editingCommunity?'Editar comunidade':'Nova comunidade'} className="mb-6"><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload={name:asString(f.get('name')),description:asString(f.get('description')),rules:asString(f.get('rules')),type:asString(f.get('type')),fee:Number(f.get('fee')),active:f.has('active')};void run(()=>api(editingCommunity?`/communities/${editingCommunity.id}`:'/communities',editingCommunity?'PATCH':'POST',payload),'Comunidade salva.').then(r=>{if(r){setShowCommunityForm(false);setEditingCommunity(null)}})}}><Input label="Nome" name="name" defaultValue={editingCommunity?.name} required/><Select label="Modelo" name="type" defaultValue={editingCommunity?.type||'free'} options={ [['free','Gratuita'],['paid','Por assinatura']] }/><Input label="Mensalidade de referência (R$)" name="fee" type="number" min={0} defaultValue={editingCommunity?.fee||0}/><TextArea label="Descrição" name="description" defaultValue={editingCommunity?.description||''}/><TextArea label="Regras" name="rules" defaultValue={editingCommunity?.rules||''}/><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="active" defaultChecked={editingCommunity?.active!==false}/> Comunidade ativa</label><div className="flex gap-2"><Button type="submit" disabled={busy}>Salvar comunidade</Button><Button kind="secondary" onClick={()=>setShowCommunityForm(false)}>Cancelar</Button></div></form></Panel>}<div className="grid gap-4 lg:grid-cols-2">{allowed.map((c,i)=><article className="table-card" key={c.id}><img src={i%2?cover.player:cover.explore} className="cover" alt="Cidadela de fantasia"/><div className="p-5"><div className="flex items-center justify-between"><h3 className="text-xl">{c.name}</h3><Badge value={c.active?'open':'closed'}/></div><p className="mt-2 text-sm text-mist">{c.description}</p><p className="my-4 text-xs text-gold">{c.type==='paid'?`Comunidade por assinatura · ${money(c.fee)}`:'Comunidade gratuita'}</p><Button onClick={()=>{setEditingCommunity(c);setShowCommunityForm(true);window.scrollTo({top:0,behavior:'smooth'})}}>Editar informações</Button></div></article>)}</div></>}
 function Dues(){const eligible=data!.communities.filter(c=>c.adminId===me?.id&&c.type==='paid');return <>{head('Controle de Mensalidades','Registre apenas a situação administrativa; sem processar pagamentos.')}<div className="grid gap-5 xl:grid-cols-[360px_1fr]"><Panel title="Novo registro"><form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(()=>api('/dues','POST',{communityId:asString(f.get('communityId')),userId:asString(f.get('userId')),period:asString(f.get('period')),amount:Number(f.get('amount')),due:asString(f.get('due'))}),'Mensalidade cadastrada.').then(r=>{if(r)e.currentTarget?.reset?.()})}}><Select label="Comunidade" name="communityId" options={eligible.map(c=>[c.id,c.name])}/><Select label="Membro" name="userId" options={data!.users.filter(u=>eligible.some(c=>u.joined?.includes(c.id))).map(u=>[u.id,u.name])}/><Input label="Competência" name="period" type="month" defaultValue={today().slice(0,7)} required/><Input label="Vencimento" name="due" type="date" defaultValue={today()} required/><Input label="Valor (R$)" name="amount" type="number" defaultValue={40} min={0}/><Button disabled={busy||!eligible.length} type="submit">Cadastrar</Button></form></Panel><Panel title="Histórico de mensalidades"><div className="scroller"><table className="data-table"><thead><tr><th>Membro</th><th>Comunidade</th><th>Competência</th><th>Valor</th><th>Vencimento</th><th>Situação</th><th>Atualizar</th></tr></thead><tbody>{data!.dues.map(d=><tr key={d.id}><td>{user(d.userId)?.name}</td><td>{community(d.communityId)?.name}</td><td>{d.period}</td><td>{money(d.amount)}</td><td>{date(d.due)}</td><td><Badge value={d.status}/></td><td><select aria-label="Atualizar situação" className="field min-w-[110px] !py-2" value={d.status} disabled={busy} onChange={e=>void run(()=>api(`/dues/${d.id}`,'PATCH',{status:e.target.value}),'Situação atualizada.')}><option value="pending">Pendente</option><option value="paid">Pago</option><option value="late">Atrasado</option></select></td></tr>)}</tbody></table></div>{!data!.dues.length&&<Empty text="Nenhum registro de mensalidade."/>}</Panel></div></>}
 function Reports(){const t=data!.tables.filter(t=>community(t.communityId)?.adminId===me?.id),r=data!.requests.filter(r=>t.some(x=>x.id===r.tableId));const totals=data!.sessions.filter(s=>t.some(x=>x.id===s.tableId)).flatMap(x=>Object.values(x.attendance||{}));return <>{head('Relatórios e Indicadores','Indicadores calculados com dados reais do banco local.')}<div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={<Castle size={18}/>} label="Comunidades" value={data!.communities.filter(c=>c.adminId===me?.id).length}/><Metric icon={<Users size={18}/>} label="Membros" value={data!.users.length}/><Metric icon={<Swords size={18}/>} label="Mesas" value={t.length}/><Metric icon={<Check size={18}/>} label="Presenças registradas" value={totals.filter(v=>v==='present').length}/></div><div className="grid gap-5 xl:grid-cols-2"><Panel title="Ocupação das mesas"><div className="space-y-5">{t.map(g=><div key={g.id}><div className="mb-2 flex justify-between gap-3 text-xs"><span>{g.name}</span><strong className="text-gold">{members(g,data!.requests).length}/{g.capacity}</strong></div><div className="h-2 overflow-hidden rounded-full bg-[#08160e]"><div style={{width:`${100*members(g,data!.requests).length/g.capacity}%`}} className="h-full rounded-full bg-gold"/></div></div>)}</div></Panel><Panel title="Inscrições por situação"><div className="space-y-4">{['pending','approved','rejected','waitlisted','cancelled'].map(v=><div key={v} className="flex items-center gap-3"><span className="w-24 text-xs text-mist">{STATUS[v]}</span><div className="h-3 flex-1 overflow-hidden rounded-full bg-[#06170f]"><div className="h-full rounded-full bg-[#33865d]" style={{width:`${Math.round(100*r.filter(x=>x.status===v).length/Math.max(r.length,1))}%`}}/></div><strong className="w-6 text-right text-xs">{r.filter(x=>x.status===v).length}</strong></div>)}</div></Panel><Panel title="Participação nas sessões"><p className="text-sm text-mist">Presenças: <strong className="text-ivory">{totals.filter(v=>v==='present').length}</strong></p><p className="mt-3 text-sm text-mist">Ausências: <strong className="text-ivory">{totals.filter(v=>v==='absent').length}</strong></p></Panel><Panel title="Atividade recente"><div className="space-y-3">{data!.activity.slice(0,8).map(a=><div className="border-b border-gold/10 pb-2 text-xs" key={a.id}><p>{a.text}</p><span className="mt-1 block text-mist">{new Date(a.date).toLocaleString('pt-BR')}</span></div>)}</div></Panel></div></>}
 function Notifications(){return <>{head('Notificações','Avisos sobre vagas, inscrições e eventos das suas mesas.',<Button kind="secondary" disabled={busy} onClick={()=>void run(()=>api('/notices/read-all','POST',{}),'Notificações marcadas como lidas.')}>Marcar todas como lidas</Button>)}<div className="grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><Panel title="Central de notificações"><div>{data!.notices.length?data!.notices.map(n=><div key={n.id} className={`row flex items-start gap-3 ${!n.read?'bg-[#173a2a]/40':''}`}><div className="mt-1 rounded-lg border border-gold/25 p-2 text-gold"><Bell size={17}/></div><div className="min-w-0 flex-1"><strong className="text-xs text-gold">{eventLabels[n.type]||'Notificação'}</strong><p className="mt-1 text-sm">{n.text}</p><span className="mt-2 block text-xs text-mist">{new Date(n.date).toLocaleString('pt-BR')}</span></div>{!n.read&&<Button kind="secondary" disabled={busy} onClick={()=>void run(()=>api(`/notices/${n.id}`,'PATCH',{}),'Notificação lida.')}>Lida</Button>}</div>):<Empty text="Nenhuma notificação disponível."/>}</div></Panel><Panel title="WhatsApp demonstrativo"><p className="mb-4 text-sm leading-6 text-mist">As mensagens abaixo não foram enviadas a um telefone. São registros de simulação.</p>{data!.whatsappLog.slice(0,9).map(w=><div key={w.id} className="row"><span className="chip gold">Simulado</span><p className="mt-2 text-xs">{w.text}</p></div>)}{!data!.whatsappLog.length&&<Empty text="Nenhuma simulação registrada."/>}<Button className="mt-4" kind="secondary" onClick={()=>goto('preferencias')}>Configurar notificações</Button></Panel></div></>}
 function Preferences(){const pref=me!.notify||{inApp:true,whatsapp:false,types:[],lead:3,hours:'09:00-21:00'};const [types,setTypes]=useState<string[]>(pref.types||[]);return <>{head('Preferências de Notificação','Controle os avisos recebidos pela plataforma e a simulação de WhatsApp.')}<div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Configurações de avisos"><form className="space-y-6" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(()=>api(`/users/${me!.id}`,'PATCH',{phone:asString(f.get('phone')),notify:{inApp:f.has('inApp'),whatsapp:f.has('whatsapp'),types,lead:Number(f.get('lead')),hours:asString(f.get('hours'))}}),'Preferências atualizadas.')}}><Input label="Telefone (opcional)" name="phone" defaultValue={me?.phone||''}/><label className="flex gap-3 text-sm"><input type="checkbox" name="inApp" defaultChecked={pref.inApp!==false}/> Receber notificações internas</label><label className="flex gap-3 text-sm"><input type="checkbox" name="whatsapp" defaultChecked={pref.whatsapp}/> Autorizo notificações por WhatsApp (simulação)</label><div className="grid gap-3 sm:grid-cols-2"><Select name="lead" label="Lembrete antes da sessão" defaultValue={String(pref.lead||3)} options={ [['1','1 hora'],['3','3 horas'],['12','12 horas'],['24','24 horas']] }/><Select name="hours" label="Horário permitido" defaultValue={pref.hours||'09:00-21:00'} options={ [['09:00-21:00','9h às 21h'],['08:00-18:00','8h às 18h'],['00:00-23:59','Qualquer horário']] }/></div><div><span className="label">Tipos de aviso</span><div className="grid gap-3 sm:grid-cols-2">{Object.entries(eventLabels).map(([k,v])=><label key={k} className="flex items-center gap-2 rounded-lg border border-gold/15 p-3 text-sm"><input type="checkbox" checked={types.includes(k)} onChange={e=>setTypes(x=>e.target.checked?[...x,k]:x.filter(t=>t!==k))}/>{v}</label>)}</div></div><Button type="submit" disabled={busy}>Salvar preferências</Button></form></Panel><Panel title="Sobre o canal"><p className="text-sm leading-7 text-mist">Quando uma vaga é liberada ou uma sessão alterada, o sistema verifica os eventos selecionados. Se houver autorização, cria um registro de envio simulado no histórico.</p><p className="mt-3 text-sm leading-7 text-mist">O envio real depende de integração futura com a API do WhatsApp e não faz parte da demonstração.</p><Button className="mt-6" kind="secondary" onClick={()=>goto('notificacoes')}>Abrir histórico</Button></Panel></div></>}
 function Profile(){const [commId,setCommId]=useState(data!.communities[0]?.id||'');const [availableDays,setAvailableDays]=useState<number[]>(me?.days||[]);const [favourites,setFavourites]=useState<string[]>(me?.systems||[]);return <>{head('Meu Perfil','Atualize suas preferências de jogo e dados pessoais.')}<div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Informações pessoais"><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(()=>api(`/users/${me!.id}`,'PATCH',{name:asString(f.get('name')),phone:asString(f.get('phone')),mode:asString(f.get('mode')),systems:favourites,days:availableDays}),'Perfil atualizado.')}}><Input label="Nome" name="name" defaultValue={me!.name} required/><label><span className="label">E-mail</span><input className="field opacity-75" disabled value={me!.email}/></label><Input label="Telefone" name="phone" defaultValue={me!.phone||''}/><Select label="Modalidade favorita" name="mode" defaultValue={me!.mode||'Online'} options={ [['Online','Online'],['Presencial','Presencial'],['Híbrida','Híbrida']] }/><div className="col-span-full"><span className="label">Sistemas favoritos</span><div className="flex flex-wrap gap-2">{SYSTEMS.map(sys=><label className="flex items-center gap-2 rounded-md border border-gold/20 px-3 py-2 text-xs" key={sys}><input type="checkbox" checked={favourites.includes(sys)} onChange={e=>setFavourites(xs=>e.target.checked?[...xs,sys]:xs.filter(x=>x!==sys))}/>{sys}</label>)}</div></div><div className="col-span-full"><span className="label">Dias disponíveis</span><div className="flex flex-wrap gap-2">{DOW.map((day,i)=><label className="flex items-center gap-2 rounded-md border border-gold/20 px-3 py-2 text-xs" key={day}><input type="checkbox" checked={availableDays.includes(i)} onChange={e=>setAvailableDays(xs=>e.target.checked?[...xs,i]:xs.filter(x=>x!==i))}/>{day}</label>)}</div></div><div className="col-span-full"><Button type="submit" disabled={busy}>Salvar alterações</Button></div></form></Panel><div className="space-y-5"><Panel title="Minha conta"><div className="flex items-center gap-3"><Avatar name={me!.name}/><div><strong>{me!.name}</strong><p className="text-xs text-mist">{ROLE[me!.role]}</p></div></div><p className="mt-4 text-xs text-mist">A conta foi criada para fins de demonstração do projeto acadêmico.</p></Panel>{me?.role==='player'&&<Panel title="Solicitar acesso de Mestre"><p className="text-sm text-mist">Peça autorização para criar mesas em uma comunidade.</p><div className="mt-4"></div><select value={commId} onChange={e=>setCommId(e.target.value)} className="field my-3" aria-label="Selecionar comunidade para solicitação">{data!.communities.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><Button disabled={busy} onClick={()=>void run(()=>api('/master-applications','POST',{communityId:commId}),'Pedido enviado para o Administrador.')}>Solicitar habilitação</Button></Panel>}</div></div></>}
 const renderPage=():ReactNode=>{if(page==='inicio')return <Landing/>;if(page==='login'||!me||!data)return <Login/>;switch(page){case 'painel':return <Dashboard/>;case 'explorar':return <Explorer/>;case 'comunidades':return <Communities/>;case 'administrar-comunidades':return me.role==='admin'?<AdminCommunities/>:<Empty text="Área restrita."/>;case 'minhas-mesas':return <MyTables/>;case 'inscricoes':return <Requests/>;case 'agenda':return <Agenda/>;case 'presencas':return me.role==='player'?<Empty text="Área restrita a mestres e administradores."/>:<Attendance/>;case 'usuarios':return me.role==='admin'?<AdminUsers/>:<Empty text="Acesso restrito ao Administrador."/>;case 'mensalidades':return me.role==='admin'?<Dues/>:<Empty text="Acesso restrito ao Administrador."/>;case 'relatorios':return me.role==='admin'?<Reports/>:<Empty text="Acesso restrito ao Administrador."/>;case 'notificacoes':return <Notifications/>;case 'preferencias':return <Preferences/>;case 'perfil':return <Profile/>;default:return <Dashboard/>;}};
 return <div className="relative min-h-screen bg-forest text-ivory"><div className={`bg-scene ${page==='inicio'?'landing-scene':''}`} style={{backgroundImage:`url('${scene}')`}}/><Topbar/>{me&&page!=='inicio'&&page!=='login'?<div className="mx-auto grid max-w-[1800px] lg:grid-cols-[245px_minmax(0,1fr)]"><Sidebar/><main className="min-w-0 px-4 py-7 md:px-8 lg:py-9">{renderPage()}</main></div>:renderPage()}{notice&&<div role="status" className="fixed bottom-5 right-5 z-50 max-w-[400px] rounded-xl border border-gold/40 bg-[#122c20] px-5 py-4 text-sm text-ivory shadow-2xl">{notice}</div>}</div>;
}
